-- Particles game: 3 sets, 16 questions, 16 written sentences.
--
-- Generated by `pnpm -C nihongo/backend seed:particles` from
-- backend/src/pipeline/data/particles. Do not edit: change the data and
-- generate a new seed.
--
-- Every set, and every set given new questions, has a pending row in the admin
-- review queue. Approving it is the only thing that puts its questions in the
-- game and publishes the sentences written for them.
--
-- Idempotent: nothing here overwrites a set, a question, a sentence or a
-- review decision.

-- Sentences written for the Particles lessons: unpublished until their set is approved.
SELECT v.id, 'lang-ja', v.text, v.reading, ll.id, 'authored', false, v.text, v.voice
FROM (VALUES
  ('sent-ptc-ni-frequency-1', '週に二かい友達に会います。', 'しゅう に にかい ともだち に あいます。', 'I meet my friend twice a week.', 'Otoya (Enhanced)'),
  ('sent-ptc-ni-frequency-2', '月に一度母に電話します。', 'つき に いちど はは に でんわ します。', 'I call my mother once a month.', 'Otoya (Enhanced)'),
  ('sent-ptc-ni-frequency-3', '一年に一かい日本へ行きます。', 'いちねん に いっかい にほん え いきます。', 'I go to Japan once a year.', 'Otoya (Enhanced)'),
  ('sent-ptc-ni-frequency-4', '一日に二かいメールを見ます。', 'いちにち に にかい メール お みます。', 'I check my email twice a day.', 'Kyoko (Enhanced)'),
  ('sent-ptc-ni-frequency-5', '週に三かい学校へ行きます。', 'しゅう に さんかい がっこう え いきます。', 'I go to school three times a week.', 'Otoya (Enhanced)'),
  ('sent-ptc-ni-frequency-6', '月に二かい映画を見ます。', 'つき に にかい えいが お みます。', 'I watch a movie twice a month.', 'Kyoko (Enhanced)'),
  ('sent-ptc-ka-or-1', '水かお茶を飲みます。', 'みず か おちゃ お のみます。', 'I will drink water or tea.', 'Kyoko (Enhanced)'),
  ('sent-ptc-ka-or-2', '月曜日か火曜日に行きます。', 'げつようび か かようび に いきます。', 'I will go on Monday or Tuesday.', 'Otoya (Enhanced)'),
  ('sent-ptc-ka-or-3', 'ペンかえんぴつで書きます。', 'ペン か えんぴつ で かきます。', 'I write with a pen or a pencil.', 'Otoya (Enhanced)'),
  ('sent-ptc-ka-or-4', 'りんごかバナナを食べます。', 'りんご か バナナ お たべます。', 'I will eat an apple or a banana.', 'Kyoko (Enhanced)'),
  ('sent-ptc-ka-or-5', '父か母に聞きます。', 'ちち か はは に ききます。', 'I will ask my father or my mother.', 'Kyoko (Enhanced)'),
  ('sent-ptc-ya-particle-1', 'つくえの上にペンやノートがあります。', 'つくえ の うえ に ペン や ノート が あります。', 'On the desk there are pens, notebooks and so on.', 'Kyoko (Enhanced)'),
  ('sent-ptc-ya-particle-2', 'りんごやバナナを買いました。', 'りんご や バナナ お かいました。', 'I bought apples, bananas and the like.', 'Kyoko (Enhanced)'),
  ('sent-ptc-ya-particle-3', '日曜日はそうじやせんたくなどをします。', 'にちようび わ そうじ や せんたく など お します。', 'On Sundays I do cleaning, laundry and so on.', 'Otoya (Enhanced)'),
  ('sent-ptc-ya-particle-4', '犬や猫が好きです。', 'いぬ や ねこ が すき です。', 'I like dogs, cats and other animals.', 'Otoya (Enhanced)'),
  ('sent-ptc-ya-particle-5', 'パンやたまごを食べます。', 'パン や たまご お たべます。', 'I eat bread, eggs and the like.', 'Kyoko (Enhanced)')
) AS v(id, text, reading, en, voice)
JOIN language_levels ll ON ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (id) DO NOTHING;

