-- ni-frequency: 6 more questions

SELECT v.id, 'pts-ja-ni-frequency', s.id, v.blank_start, v.blank_end, v.answer, v.also_right, v.wrong, v.note, v.sort_index
FROM (VALUES
  ('pts-ja-ni-frequency-q4', '週に二かい友達に会います。', 1, 2, 'に', ARRAY[]::text[], ARRAY['が', 'を', 'で']::text[], 'に after a period of time says "per": twice a week.', 4),
  ('pts-ja-ni-frequency-q5', '月に一度母に電話します。', 1, 2, 'に', ARRAY[]::text[], ARRAY['で', 'を', 'の']::text[], 'に ties the count to the period: once per month.', 5),
  ('pts-ja-ni-frequency-q6', '一年に一かい日本へ行きます。', 2, 3, 'に', ARRAY[]::text[], ARRAY['を', 'と', 'が']::text[], 'に gives the rate: once per year.', 6),
  ('pts-ja-ni-frequency-q7', '一日に二かいメールを見ます。', 2, 3, 'に', ARRAY[]::text[], ARRAY['が', 'を', 'の']::text[], 'に after a day says "per day": twice a day.', 7),
  ('pts-ja-ni-frequency-q8', '週に三かい学校へ行きます。', 1, 2, 'に', ARRAY[]::text[], ARRAY['を', 'と', 'が']::text[], 'に after 週 says "per week": three times a week.', 8),
  ('pts-ja-ni-frequency-q9', '月に二かい映画を見ます。', 1, 2, 'に', ARRAY[]::text[], ARRAY['が', 'を', 'で']::text[], 'に gives the rate: twice per month.', 9)
) AS v(id, text, blank_start, blank_end, answer, also_right, wrong, note, sort_index)
CROSS JOIN LATERAL (
  SELECT id FROM sentences
  WHERE language_id = 'lang-ja' AND text = v.text
  ORDER BY published DESC, created_at, id LIMIT 1
) s
WHERE EXISTS (SELECT 1 FROM particle_sets WHERE id = 'pts-ja-ni-frequency')
ON CONFLICT DO NOTHING;

SELECT 'crq-pts-ja-ni-frequency-183', 'lang-ja', 'particle_sets', 'pts-ja-ni-frequency', 'update', '{"point":"ni-frequency","questions":6}'::jsonb, 'ai', 1500, 'pending'
WHERE EXISTS (SELECT 1 FROM particle_sets WHERE id = 'pts-ja-ni-frequency')
  AND NOT EXISTS (SELECT 1 FROM content_review_queue WHERE target_table = 'particle_sets' AND target_id = 'pts-ja-ni-frequency' AND status = 'pending')
ON CONFLICT DO NOTHING;

-- ka-or: 5 more questions

SELECT v.id, 'pts-ja-ka-or', s.id, v.blank_start, v.blank_end, v.answer, v.also_right, v.wrong, v.note, v.sort_index
FROM (VALUES
  ('pts-ja-ka-or-q6', '水かお茶を飲みます。', 1, 2, 'か', ARRAY[]::text[], ARRAY['と', 'を', 'が']::text[], 'か between two nouns means "or". と would mean drinking both.', 6),
  ('pts-ja-ka-or-q7', '月曜日か火曜日に行きます。', 3, 4, 'か', ARRAY[]::text[], ARRAY['と', 'を', 'が']::text[], 'か offers a choice of days. と would mean going on both.', 7),
  ('pts-ja-ka-or-q8', 'ペンかえんぴつで書きます。', 2, 3, 'か', ARRAY[]::text[], ARRAY['と', 'を', 'が']::text[], 'か joins the two options: a pen or a pencil.', 8),
  ('pts-ja-ka-or-q9', 'りんごかバナナを食べます。', 3, 4, 'か', ARRAY[]::text[], ARRAY['と', 'が', 'に']::text[], 'か gives a choice of one fruit or the other.', 9),
  ('pts-ja-ka-or-q10', '父か母に聞きます。', 1, 2, 'か', ARRAY[]::text[], ARRAY['と', 'を', 'が']::text[], 'か means "or": one of the two parents, not both.', 10)
) AS v(id, text, blank_start, blank_end, answer, also_right, wrong, note, sort_index)
CROSS JOIN LATERAL (
  SELECT id FROM sentences
  WHERE language_id = 'lang-ja' AND text = v.text
  ORDER BY published DESC, created_at, id LIMIT 1
) s
WHERE EXISTS (SELECT 1 FROM particle_sets WHERE id = 'pts-ja-ka-or')
ON CONFLICT DO NOTHING;

SELECT 'crq-pts-ja-ka-or-183', 'lang-ja', 'particle_sets', 'pts-ja-ka-or', 'update', '{"point":"ka-or","questions":5}'::jsonb, 'ai', 1501, 'pending'
WHERE EXISTS (SELECT 1 FROM particle_sets WHERE id = 'pts-ja-ka-or')
  AND NOT EXISTS (SELECT 1 FROM content_review_queue WHERE target_table = 'particle_sets' AND target_id = 'pts-ja-ka-or' AND status = 'pending')
ON CONFLICT DO NOTHING;

